window.VORLEN_CARDS = [{"n": 1, "l1": "Restaurant notice RN-03", "l2": "Site: Berghaus Grauegg", "b": "Allergen information for every dish is kept in a folder at the counter and is shown on request. The kitchen works with celery, mustard, milk and gluten daily and cannot guarantee separate preparation. Desserts without nuts are marked on the board. Sara Wenger trains the counter staff on this before each season."}, {"n": 2, "l1": "Maintenance log ML-126", "l2": "Component: Chair grips, Sesselbahn Arven", "b": "All two hundred and ten grips were tested on 8 September 2025 with the pull gauge. Four fell below the holding force and were sent back to the works for overhaul. Spares were fitted the same day. Nadia Sterchi countersigned the record and the next full test is due in September 2026."}, {"n": 3, "l1": "Weather and closure rule WR-05", "l2": "Installation: Sesselbahn Arven", "b": "The bubble covers are lowered by the loading crew when sleet is falling. Operation stops if the wind at the top station reaches 55 km/h, or if the temperature with wind chill falls below minus 28 degrees. Guests already on the line are unloaded at the top. Nadia Sterchi reviews the log weekly."}, {"n": 4, "l1": "Service notice SN-15", "l2": "Installation: Sesselbahn Arven", "b": "First departure from Malbrunn Alp at 08:30 and last upward departure at 16:00 in winter. In summer the chairlift runs from 09:30 to 16:45 for walkers and for mountain bikes. It closes for the annual revision in the first two weeks of November. Bicycles are carried on a rear rack."}, {"n": 5, "l1": "Training record TR-09", "l2": "Course: Snow safety and blasting", "b": "Held on 4 November 2025 on the ridge above Bodmi with the cantonal instructor. Six employees attended and four of them hold the blasting permit. The permit is renewed every five years and requires a practical test. Nadia Sterchi records the permit numbers separately from the attendance list."}, {"n": 6, "l1": "Supplier contract clause SC-16", "l2": "Supplier: Talbeck Textil AG, framework agreement 2025", "b": "Clause 2.2. Winter jackets are delivered by 15 September each year in the quantities ordered in June. Clause 2.3. A garment that fails at a seam within one season is replaced at no cost. Clause 2.4. Unused stock may be returned once a year up to a value of 4,000 francs."}, {"n": 7, "l1": "Weather and closure rule WR-01", "l2": "Installation: Gondelbahn Malbrunn", "b": "Wind is measured at the drive station and read as a ten minute average. Operation stops when that average reaches 65 km/h. In thunderstorms the line is cleared as soon as lightning is detected within 5 kilometres. Passengers already on the line are brought to the nearest station before the drive is shut down."}, {"n": 8, "l1": "Technical data sheet TD-04", "l2": "Installation: Sesselbahn Bodmi", "b": "Fixed grip four seat chairlift from Sattel to Bodmi, in service since 2004. Track length 1,180 metres, vertical rise 370 metres. Ninety two chairs run at 2.3 metres per second and the ride takes 8 minutes. Hourly capacity is 1,800 passengers. The line crosses the piste twice."}, {"n": 9, "l1": "Lost property record LP-74", "l2": "Item: Pair of poles, aluminium, marked with tape", "b": "Handed in at the Bodmi top station on 26 February 2026 by the lift attendant. They were found leaning against the fence at the unloading area. Poles are the most common item in the store and are kept for six weeks. These were collected the following weekend by a guest from the ski school."}, {"n": 10, "l1": "Service notice SN-12", "l2": "Installation: Sesselbahn Bodmi", "b": "The chairlift runs only in the winter season, from the middle of December to the end of March. First departure is at 09:00 and the last upward departure at 16:00. It does not run in summer, and the chairs are taken off and stored in the valley during April."}, {"n": 11, "l1": "Weather and closure rule WR-03", "l2": "Installation: Standseilbahn Chalperen", "b": "The funicular runs in almost all weather because the track is sheltered for most of its length. It stops only when water on the track is detected by the drainage alarm, or when visibility at the passing loop falls below 20 metres. Livio Bandini logs each stoppage and the reason for it."}, {"n": 12, "l1": "Maintenance log ML-131", "l2": "Component: Brake pads, Standseilbahn Chalperen", "b": "The service brake pads on both cars were renewed on 2 December 2025 at 3 millimetres of remaining thickness. The emergency brake was tested afterwards with a full load and stopped the car within 4.2 metres. Beat Halter signed the record. Pads are inspected every two months during the winter season."}, {"n": 13, "l1": "Training record TR-02", "l2": "Course: Evacuation of a stopped installation", "b": "Held on 14 October 2025 at the Malbrunn drive station and run by an external instructor. Nineteen employees attended, including all six loading crews. The course certifies rope descent and stretcher handling, and the certificate is valid for three years. Beat Halter keeps the attendance list and the signed practice sheets."}, {"n": 14, "l1": "Service notice SN-06", "l2": "Installation: Gondelbahn Malbrunn", "b": "First departure from Vorlen Dorf at 08:00 and last upward departure at 16:15 in winter. The line runs continuously and follows no timetable. It closes for the annual revision from 4 May to 12 June. On 24 and 31 December the last departure is brought forward to 15:00."}, {"n": 15, "l1": "Staff handbook section SH-07", "l2": "Section: Uniform and appearance", "b": "The company jacket and the name badge are worn at all times in view of guests. Jackets are issued in October and returned at the end of April for cleaning. A replacement badge costs 15 francs and is ordered through the station master. Personal headwear is permitted if it carries no other company name."}, {"n": 16, "l1": "Lost property record LP-70", "l2": "Item: Rucksack, blue, 30 litres", "b": "Handed in at the Grauegg Gipfel station on 17 February 2026 by the restaurant staff. It held a wallet, which was logged separately and locked in the office safe. The owner telephoned the same evening and collected both the next morning against a signature. Nadia Sterchi countersigned the release."}, {"n": 17, "l1": "Supplier contract clause SC-11", "l2": "Supplier: Kernli Seiltechnik AG, framework agreement 2024", "b": "Clause 6.2. Replacement haul ropes are delivered to Vorlen Dorf within 21 working days of a written order. For each working day of delay the supplier owes 480 francs, capped at 12,000 francs per order. Clause 6.3. The warranty on splicing work is 36 months from handover. Clause 6.4. Orders above 50,000 francs need a second signature."}, {"n": 18, "l1": "Restaurant notice RN-01", "l2": "Site: Berghaus Grauegg", "b": "The terrace holds ninety seats and is not reservable. Inside seating is held for groups only, through the restaurant manager. Dogs are welcome on the terrace but not in the dining room. The kitchen takes its last hot order 30 minutes before closing. Sara Wenger holds the key to the ski depot."}, {"n": 19, "l1": "Lost property record LP-58", "l2": "Item: Ski helmet, black, size M", "b": "Handed in at the Sattel station on 21 January 2026 by a member of the loading crew. It was found under a chair at the unloading ramp. Items are held in the store for six months. This one was collected on 3 February 2026 by a guest who described the sticker on the back correctly."}, {"n": 20, "l1": "Incident report IR-2026-014", "l2": "Installation: Standseilbahn Chalperen", "b": "On 28 February 2026 the upper car came to a controlled halt 60 metres below Sattel after a door contact failed to confirm. Thirty one guests were walked up the emergency stairway by Livio Bandini and two staff. The fault was traced to a loose plug and cleared in 35 minutes. Service resumed at 12:05."}, {"n": 21, "l1": "Staff handbook section SH-21", "l2": "Section: Reporting an injury to a guest", "b": "Any injury to a guest is reported to the safety officer on the same day, in writing, however slight it appears. The employee who was present writes the report, not the supervisor. Nadia Sterchi keeps the file for ten years. Nothing is said to the press by anyone other than the head of operations."}, {"n": 22, "l1": "Supplier contract clause SC-22", "l2": "Supplier: Kernli Seiltechnik AG, testing annexe", "b": "Clause 9.1. The supplier carries out the magnetic test with its own equipment and issues the certificate. Clause 9.2. The test is charged at 3,800 francs for each installation, travel included. Clause 9.3. A repeat test within twelve months of a negative result is carried out at half that price."}, {"n": 23, "l1": "Restaurant notice RN-02", "l2": "Site: Berghaus Grauegg", "b": "Open daily from 08:30 to 16:00 in winter and from 09:00 to 17:00 in summer. Barley soup 9.50 francs, cheese roll 7.00 francs, hot chocolate 4.50 francs. The barley soup contains celery. Card payment is accepted from 20 francs. Groups above 12 people book two days ahead on extension 214."}, {"n": 24, "l1": "Staff handbook section SH-11", "l2": "Section: Breaks and meals", "b": "Staff on a shift longer than six hours take an unpaid break of 45 minutes, and staff on a shift longer than nine hours take 60 minutes. Breaks are taken away from the loading area. A hot meal at either mountain buffet costs staff 6 francs, and the reduction does not extend to guests."}, {"n": 25, "l1": "Supplier contract clause SC-08", "l2": "Supplier: Ostwind Antriebe AG, framework agreement 2022", "b": "Clause 5.4. An overhauled main drive is returned to service within 30 calendar days of collection. Clause 5.5. A loan drive is provided free of charge from day 31 onward. Clause 5.6. The supplier guarantees spare parts for fifteen years from delivery, and price rises are capped at three per cent a year."}, {"n": 26, "l1": "Training record TR-12", "l2": "Course: Guest service and complaints", "b": "Held on 11 November 2025 in the meeting room at Vorlen Dorf. Thirty one employees attended, including the whole buffet staff. There is no certificate and no expiry date. Ruth Amgarten ran the second half herself and asked every attendee to write one sentence about a complaint they had handled badly."}, {"n": 27, "l1": "Incident report IR-2026-011", "l2": "Installation: Luftseilbahn Grauegg", "b": "On 14 February 2026 the cable car did not open in the morning. Gusts of 81 km/h were recorded at the Sattel mast from 06:40, above the limit set for this installation. Ruth Amgarten released the first departure at 11:20 once the average had fallen back. Ninety four guests waited below and were given vouchers."}, {"n": 28, "l1": "Lost property record LP-61", "l2": "Item: Camera, compact, in a red case", "b": "Handed in at the valley station on 29 January 2026 by a guest who found it on a bench. The memory card was removed and stored separately by Livio Bandini. Nobody has claimed it since. It will be given to the village police when the six month period ends in July 2026."}, {"n": 29, "l1": "Technical data sheet TD-03", "l2": "Installation: Standseilbahn Chalperen", "b": "Funicular from Vorlen Dorf to Sattel, opened in 1954 and the oldest installation in the company. Track length 1,460 metres, vertical rise 680 metres, with one passing loop at the midpoint. Two cars carry 120 passengers each. The maximum gradient is 61 per cent and the journey takes 7 minutes."}, {"n": 30, "l1": "Service notice SN-09", "l2": "Installation: Standseilbahn Chalperen", "b": "Departures on the hour and the half hour from 07:30 to 18:00 all year. Two extra evening departures run on Friday and Saturday in the winter season, at 19:30 and at 21:00. The cars carry luggage and bicycles at no charge. The annual revision falls in the last two weeks of October."}, {"n": 31, "l1": "Incident report IR-2026-007", "l2": "Installation: Sesselbahn Arven", "b": "On 3 February 2026 a chair was halted at 14:22 when a rucksack strap caught in the closing bar at the loading point. The line ran again after 4 minutes. Livio Bandini logged the stop and briefed the loading crew the same evening. The guest continued the ride without assistance and made no complaint at the office."}, {"n": 32, "l1": "Supplier contract clause SC-04", "l2": "Supplier: Frehner Elektro GmbH, framework agreement 2023", "b": "Clause 3.1. A call out for a drive fault is answered on site within four hours between 06:00 and 20:00, and within eight hours outside those times. Clause 3.2. Travel is charged at a flat 220 francs per call out. Clause 3.3. Parts held in the valley store remain the property of the supplier until they are fitted."}, {"n": 33, "l1": "Technical data sheet TD-05", "l2": "Installation: Sesselbahn Arven", "b": "Detachable six seat chairlift from Malbrunn Alp to Arven, in service since 2015. Track length 1,640 metres, vertical rise 360 metres. Chairs run at 5 metres per second and carry bubble covers and heated seats. Hourly capacity is 2,800 passengers. The ride takes 6 minutes in normal operation."}, {"n": 34, "l1": "Service notice SN-03", "l2": "Installation: Luftseilbahn Grauegg", "b": "First departure from Sattel at 08:45 and last departure from the summit at 16:30 in the winter season. In summer the last departure moves to 17:15. The line closes for the annual revision from 20 April to 29 May. Departures run every twenty minutes outside the peak hours."}, {"n": 35, "l1": "Maintenance log ML-112", "l2": "Component: Haul rope, Luftseilbahn Grauegg", "b": "A magnetic test was carried out on 4 November 2025 over the full length. No broken wires were found in the outer layer and the reduction in cross section stayed under one per cent. Beat Halter signed the record. The next magnetic test falls due in November 2028 and the visual check every six months."}, {"n": 36, "l1": "Weather and closure rule WR-02", "l2": "Installation: Sesselbahn Bodmi", "b": "The line crosses two avalanche paths above the middle section. It is closed at avalanche danger level 3 and stays closed until the safety officer has released the slope. Blasting is carried out from the ridge before the first departure. Nadia Sterchi records every release in the winter log."}, {"n": 37, "l1": "Technical data sheet TD-02", "l2": "Installation: Gondelbahn Malbrunn", "b": "Detachable gondola from Vorlen Dorf to Malbrunn Alp, in service since 1998. Track length 3,210 metres, vertical rise 840 metres, fourteen towers. Sixty four cabins carry eight passengers each at up to 6 metres per second. Hourly capacity is 2,400 passengers. The drive station stands at the valley end."}, {"n": 38, "l1": "Training record TR-17", "l2": "Course: Working at height", "b": "Held on 3 December 2025 on the Malbrunn towers with the supplier's own trainer. Eight employees from the technical service attended. The certificate is valid for two years and covers harness use, anchor points and rescue from a tower. Beat Halter is the internal contact for refreshers."}, {"n": 39, "l1": "Restaurant notice RN-04", "l2": "Site: Buvette Sattel", "b": "The buvette serves soup, sandwiches and drinks from a single counter and has no table service. It is closed on Tuesday outside the school holidays and open every day during them. Payment is in cash only. The self service water tap on the north wall is free and is refilled from the spring."}, {"n": 40, "l1": "Staff handbook section SH-03", "l2": "Section: Shift swaps", "b": "A swap between two employees on the same qualification level needs no approval if it is entered in the roster two days ahead. A swap inside two days needs the written agreement of the head of operations. No employee may work more than nine days in a row. Ruth Amgarten reviews the roster each Monday."}, {"n": 41, "l1": "Restaurant notice RN-05", "l2": "Site: Buvette Sattel", "b": "Hot food is served between 11:00 and 14:30 only, because the kitchen is a single hotplate. Outside those hours the counter sells cake, sandwiches and drinks. A deposit of 2 francs is charged on every cup and is returned at the counter. Sara Wenger orders the stock once a week."}, {"n": 42, "l1": "Technical data sheet TD-01", "l2": "Installation: Luftseilbahn Grauegg", "b": "Aerial cable car from Sattel to Grauegg Gipfel, in service since 1971 and refurbished in 2009. Track length 2,840 metres, vertical rise 890 metres. Two cabins carry 80 passengers each at up to 10 metres per second. Hourly capacity is 1,200 passengers. The haul rope diameter is 46 millimetres."}, {"n": 43, "l1": "Incident report IR-2026-004", "l2": "Installation: Gondelbahn Malbrunn", "b": "On 12 January 2026 the gondola stopped at 09:14 with 46 passengers on board. The cause was a frozen limit switch on tower 6. Passengers waited 22 minutes and were brought down on the auxiliary drive at half speed. No injuries were reported. Beat Halter replaced the switch the same afternoon and the line reopened at 15:40."}, {"n": 44, "l1": "Weather and closure rule WR-04", "l2": "Installation: Luftseilbahn Grauegg", "b": "Wind is measured at the Sattel mast and read as a ten minute average. Icing on the track rope closes the line regardless of wind. Departures are suspended once the average reaches 74 km/h, and below that figure the cabins may run at reduced speed. Ruth Amgarten authorises every reopening."}, {"n": 45, "l1": "Maintenance log ML-140", "l2": "Component: Tow rope, Skilift Halten", "b": "The rope was re-spliced on 11 March 2026 during the spring shutdown. The splice measures 1,800 millimetres and was carried out by the supplier's own crew under supervision. Beat Halter signed the record. The splice is to be inspected weekly for the first eight weeks of the next season."}, {"n": 46, "l1": "Lost property record LP-63", "l2": "Item: Leather glove, brown, left hand", "b": "Handed in at the Malbrunn Alp station on 8 February 2026 by the morning shift. It was found on the floor of a cabin at the turnaround. Single gloves are kept for six weeks and then given to the second hand shop in the village. This one was never claimed."}, {"n": 47, "l1": "Training record TR-05", "l2": "Course: First aid refresher", "b": "Held on 22 October 2025 in the meeting room at Vorlen Dorf. Twenty six employees attended over two half day sittings. The certificate is valid for two years and is required of anyone working alone at a station. Nadia Sterchi ran the course and holds the register."}, {"n": 48, "l1": "Maintenance log ML-118", "l2": "Component: Gearbox, Gondelbahn Malbrunn", "b": "The oil was changed on 19 October 2025 after 4,100 running hours. Forty litres were drained and the filter replaced. The sample sent to the laboratory came back clean with no metal traces. Beat Halter signed the record. The next change falls due at 8,000 running hours or in October 2027, whichever comes first."}, {"n": 49, "l1": "Staff handbook section SH-15", "l2": "Section: Staff ski passes", "b": "Every employee on a seasonal contract receives one free pass valid on all six installations. Family passes are sold at half the public price, for a partner and for children under eighteen. Passes are personal and are withdrawn on first misuse. Applications go to Ruth Amgarten before the end of November."}, {"n": 50, "l1": "Incident report IR-2026-019", "l2": "Installation: Skilift Halten", "b": "On 6 March 2026 the tow rope slipped from the return sheave at the top station during the first run of the day. Nobody was on the lift at the time. Beat Halter reseated the rope and adjusted the tension by hand. The lift stayed shut until 10:15 while the alignment was measured twice and recorded."}];
